import{_ as c,C as u,o as s,c as m,a2 as l,b as t,w as a,a as i,E as n,a3 as d,j as o}from"./chunks/framework.CgxQ0r6v.js";const S=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Bases_de_Datos/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Bases_de_Datos/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"}'),p={name:"materias/Bases_de_Datos/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"};function A(g,e,C,D,b,B){const r=u("Mermaid");return s(),m("div",null,[e[4]||(e[4]=l('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-bases-de-datos-trayecto-ii-trimestre-v" tabindex="-1">Materia: Bases de Datos (Trayecto II - Trimestre V) <a class="header-anchor" href="#materia-bases-de-datos-trayecto-ii-trimestre-v" aria-label="Permalink to &quot;Materia: Bases de Datos (Trayecto II - Trimestre V)&quot;">​</a></h2><h3 id="eje-tematico-el-mundo-de-las-bases-de-datos-arquitectura-de-dbms-y-el-rol-del-dba" tabindex="-1">Eje Temático: El Mundo de las Bases de Datos, Arquitectura de DBMS y el Rol del DBA <a class="header-anchor" href="#eje-tematico-el-mundo-de-las-bases-de-datos-arquitectura-de-dbms-y-el-rol-del-dba" aria-label="Permalink to &quot;Eje Temático: El Mundo de las Bases de Datos, Arquitectura de DBMS y el Rol del DBA&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-superacion-del-fichero-plano" tabindex="-1">🧭 Introducción: La Superación del Fichero Plano <a class="header-anchor" href="#🧭-introduccion-la-superacion-del-fichero-plano" aria-label="Permalink to &quot;🧭 Introducción: La Superación del Fichero Plano&quot;">​</a></h2><p>En el Trayecto I aprendimos a programar algoritmos y estructuras de datos en memoria volátil (RAM) y a persistir información básica en archivos de texto o JSON. Sin embargo, en el mundo real de las instituciones públicas, ambulatorios de salud, empresas y sistemas gubernamentales, almacenar información en archivos planos convencionales (<code>.txt</code>, <code>.csv</code>) genera una crisis arquitectónica inmediata:</p><ol><li><strong>Redundancia e Inconsistencia de Datos:</strong> Los mismos datos (ej. los datos de un paciente o estudiante) se repiten en múltiples archivos dispersos. Si el usuario actualiza su dirección en un archivo pero no en los otros, el sistema entra en estado inconsistente.</li><li><strong>Dificultad en el Acceso:</strong> Para responder a una nueva consulta (ej. <em>&quot;listar los pacientes mayores de 60 años atendidos en cardiología el último mes&quot;</em>), se requeriría programar un script específico desde cero para recorrer y parsear los archivos.</li><li><strong>Aislamiento de Datos:</strong> La información se encuentra en formatos incompatibles y archivos independientes, imposibilitando correlacionar registros fácilmente.</li><li><strong>Problemas de Integridad:</strong> Es casi imposible hacer cumplir reglas de negocio universales (ej. <em>&quot;el sueldo no puede ser negativo&quot;</em> o <em>&quot;la cédula debe ser única&quot;</em>) a nivel de archivo sin duplicar código en cada programa cliente.</li><li><strong>Falta de Atomicidad ante Fallos:</strong> Si el computador se apaga en medio de una transferencia bancaria o del registro de una historia médica, el archivo queda corrupto o a medio escribir.</li><li><strong>Anomalías de Acceso Concurrente:</strong> Cuando dos secretarias o dos médicos intentan modificar el mismo archivo al mismo milisegundo, una de las actualizaciones sobrescribe y destruye a la otra.</li><li><strong>Inseguridad:</strong> Es difícil otorgar permisos granulares (ej. <em>&quot;la enfermera puede leer signos vitales pero no alterar el diagnóstico médico&quot;</em>).</li></ol><p>Para resolver de raíz todas estas problemáticas nacen los <strong>Sistemas de Bases de Datos</strong> y sus motores de gestión: los <strong>Sistemas Manejadores de Bases de Datos (SMBD / DBMS)</strong>.</p><hr><h2 id="🏛️-capitulo-i-definicion-y-evolucion-historica-de-los-dbms" tabindex="-1">🏛️ CAPÍTULO I: Definición y Evolución Histórica de los DBMS <a class="header-anchor" href="#🏛️-capitulo-i-definicion-y-evolucion-historica-de-los-dbms" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Definición y Evolución Histórica de los DBMS&quot;">​</a></h2><p>Un <strong>Sistema de Base de Datos</strong> es una colección estructurada de datos lógicamente relacionados y un conjunto de programas diseñados para acceder, manipular y administrar dichos datos de manera segura y eficiente.</p><p>El software nuclear que gobierna todo esto es el <strong>DBMS (Database Management System)</strong> o <strong>SMBD (Sistema Manejador de Bases de Datos)</strong>.</p>',12)),(s(),t(d,null,{default:a(()=>[n(r,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20App1%5B%22Aplicaci%C3%B3n%20Web%20(Node.js%2FPython)%22%5D%20--%3E%20DBMS%5B%22SISTEMA%20MANEJADOR%20DE%20BASES%20DE%20DATOS%20(DBMS)%3Cbr%3EPostgreSQL%20%2F%20MySQL%22%5D%0A%20%20%20%20App2%5B%22Aplicaci%C3%B3n%20M%C3%B3vil%20(Android%2FFlutter)%22%5D%20--%3E%20DBMS%0A%20%20%20%20App3%5B%22Cliente%20Administrativo%20(DBeaver%2FCLI)%22%5D%20--%3E%20DBMS%0A%20%20%20%20%0A%20%20%20%20subgraph%20Motor%20%5B%22N%C3%BAcleo%20Interno%20del%20DBMS%22%5D%0A%20%20%20%20%20%20%20%20DBMS%20--%3E%20QProc%5B%22Procesador%20de%20Consultas%20(Parser%2FOptimizador)%22%5D%0A%20%20%20%20%20%20%20%20DBMS%20--%3E%20TMan%5B%22Gestor%20de%20Transacciones%20(ACID)%22%5D%0A%20%20%20%20%20%20%20%20DBMS%20--%3E%20SMan%5B%22Gestor%20de%20Almacenamiento%20(Buffer%20%2F%20Disco)%22%5D%0A%20%20%20%20%20%20%20%20DBMS%20--%3E%20Dic%5B%22Diccionario%20de%20Datos%20(Cat%C3%A1logo%20del%20Sistema)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20SMan%20--%3E%20ArchivosDisco%5B(%22Almacenamiento%20F%C3%ADsico%20en%20Disco%3Cbr%3ETablas%2C%20%C3%8Dndices%20y%20Logs%22)%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o("h3",{id:"linea-de-tiempo-de-los-modelos-de-bases-de-datos",tabindex:"-1"},[i("Línea de Tiempo de los Modelos de Bases de Datos "),o("a",{class:"header-anchor",href:"#linea-de-tiempo-de-los-modelos-de-bases-de-datos","aria-label":'Permalink to "Línea de Tiempo de los Modelos de Bases de Datos"'},"​")],-1)),(s(),t(d,null,{default:a(()=>[n(r,{id:"mermaid-70",class:"mermaid",graph:"timeline%0A%20%20%20%20title%20Evoluci%C3%B3n%20de%20los%20Modelos%20de%20Bases%20de%20Datos%0A%20%20%20%201960s%20%3A%20Modelo%20Jer%C3%A1rquico%20(%C3%81rboles%20padre-hijo%2C%20ej.%20IMS%20de%20IBM)%0A%20%20%20%20%20%20%20%20%20%20%3A%20Modelo%20en%20Red%20(Grafos%20CODASYL%2C%20navegaci%C3%B3n%20por%20punteros)%0A%20%20%20%201970%20%3A%20Modelo%20Relacional%20(Edgar%20F.%20Codd)%0A%20%20%20%20%20%20%20%20%20%3A%20%C3%81lgebra%20Relacional%20y%20tablas%20matem%C3%A1ticas%0A%20%20%20%201980s%20%3A%20Consolidaci%C3%B3n%20de%20SQL%20(ANSI%2FISO)%0A%20%20%20%20%20%20%20%20%20%20%3A%20Oracle%2C%20DB2%2C%20Informix%0A%20%20%20%201990s%20%3A%20Bases%20de%20Datos%20Abiertas%20y%20Web%0A%20%20%20%20%20%20%20%20%20%20%3A%20Nacimiento%20de%20PostgreSQL%20y%20MySQL%0A%20%20%20%202000s%20%3A%20Paradigma%20NoSQL%20y%20Big%20Data%0A%20%20%20%20%20%20%20%20%20%20%3A%20Documentales%20(MongoDB)%2C%20Clave-Valor%20(Redis)%2C%20Grafos%20(Neo4j)%0A%20%20%20%202010s-Hoy%20%3A%20Motores%20NewSQL%20y%20Multi-modelo%0A%20%20%20%20%20%20%20%20%20%20%20%20%20%20%3A%20PostgreSQL%20con%20soporte%20JSON%20nativo%2C%20ACID%20distribuido%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o("hr",null,null,-1)),e[7]||(e[7]=o("h2",{id:"🏗️-capitulo-ii-la-arquitectura-ansi-sparc-de-3-niveles-y-la-independencia-de-datos",tabindex:"-1"},[i("🏗️ CAPÍTULO II: La Arquitectura ANSI/SPARC de 3 Niveles y la Independencia de Datos "),o("a",{class:"header-anchor",href:"#🏗️-capitulo-ii-la-arquitectura-ansi-sparc-de-3-niveles-y-la-independencia-de-datos","aria-label":'Permalink to "🏗️ CAPÍTULO II: La Arquitectura ANSI/SPARC de 3 Niveles y la Independencia de Datos"'},"​")],-1)),e[8]||(e[8]=o("p",null,[i("En 1975, el comité ANSI/SPARC propuso un marco arquitectónico fundamental que sigue rigiendo el diseño de todo DBMS moderno. Su objetivo supremo es "),o("strong",null,"aislar al usuario y a las aplicaciones de los detalles físicos de almacenamiento en disco"),i(".")],-1)),(s(),t(d,null,{default:a(()=>[n(r,{id:"mermaid-78",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20NivelExterno%20%5B%22NIVEL%20EXTERNO%20(Vistas%20de%20Usuario)%22%5D%0A%20%20%20%20%20%20%20%20V1%5B%22Vista%201%3A%20M%C3%B3dulo%20de%20Facturaci%C3%B3n%22%5D%0A%20%20%20%20%20%20%20%20V2%5B%22Vista%202%3A%20M%C3%B3dulo%20M%C3%A9dico%20%2F%20Citas%22%5D%0A%20%20%20%20%20%20%20%20V3%5B%22Vista%203%3A%20Reportes%20Gerenciales%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20NivelConceptual%20%5B%22NIVEL%20CONCEPTUAL%20(Esquema%20L%C3%B3gico%20Global)%22%5D%0A%20%20%20%20%20%20%20%20EC%5B%22Esquema%20Conceptual%20Completo%3Cbr%3ETablas%2C%20Claves%20Primarias%2C%20Claves%20For%C3%A1neas%20y%20Restricciones%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20NivelFisico%20%5B%22NIVEL%20INTERNO%20%2F%20F%C3%8DSICO%20(Almacenamiento%20en%20Disco)%22%5D%0A%20%20%20%20%20%20%20%20EF%5B%22Esquema%20F%C3%ADsico%3Cbr%3EBloques%20en%20disco%2C%20Estructura%20B-Tree%2C%20Heap%20Files%2C%20Compresi%C3%B3n%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20V1%20--%3E%20EC%0A%20%20%20%20V2%20--%3E%20EC%0A%20%20%20%20V3%20--%3E%20EC%0A%20%20%20%20EC%20--%3E%20EF%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[i(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=l('<h3 id="los-dos-tipos-de-independencia-de-datos" tabindex="-1">Los Dos Tipos de Independencia de Datos: <a class="header-anchor" href="#los-dos-tipos-de-independencia-de-datos" aria-label="Permalink to &quot;Los Dos Tipos de Independencia de Datos:&quot;">​</a></h3><ol><li><strong>Independencia Física de Datos:</strong> Capacidad de modificar el esquema físico (ej. cambiar de disco HDD a SSD, reorganizar los índices B-Tree o particionar archivos) sin necesidad de modificar el esquema conceptual ni las aplicaciones de los usuarios.</li><li><strong>Independencia Lógica de Datos:</strong> Capacidad de alterar el esquema conceptual (ej. añadir una nueva columna o una nueva tabla) sin tener que reescribir las vistas externas existentes ni las consultas de los usuarios que no usan esa columna.</li></ol><hr><h2 id="🌐-capitulo-iii-arquitecturas-de-despliegue-de-bases-de-datos" tabindex="-1">🌐 CAPÍTULO III: Arquitecturas de Despliegue de Bases de Datos <a class="header-anchor" href="#🌐-capitulo-iii-arquitecturas-de-despliegue-de-bases-de-datos" aria-label="Permalink to &quot;🌐 CAPÍTULO III: Arquitecturas de Despliegue de Bases de Datos&quot;">​</a></h2><p>En la práctica profesional existen tres arquitecturas predominantes para organizar la comunicación entre las aplicaciones y el DBMS:</p><h3 id="_1-arquitectura-centralizada-monolitica" tabindex="-1">1. Arquitectura Centralizada (Monolítica) <a class="header-anchor" href="#_1-arquitectura-centralizada-monolitica" aria-label="Permalink to &quot;1. Arquitectura Centralizada (Monolítica)&quot;">​</a></h3><p>El DBMS, las aplicaciones y la interfaz de usuario se ejecutan en la misma máquina física (históricamente Mainframes). El usuario interactúa mediante terminales tontas.</p><h3 id="_2-arquitectura-cliente-servidor-2-capas" tabindex="-1">2. Arquitectura Cliente-Servidor (2 Capas) <a class="header-anchor" href="#_2-arquitectura-cliente-servidor-2-capas" aria-label="Permalink to &quot;2. Arquitectura Cliente-Servidor (2 Capas)&quot;">​</a></h3><ul><li><strong>Cliente (Front-End):</strong> Ejecuta la interfaz gráfica de usuario y la lógica de negocio. Se comunica directamente con la base de datos mediante protocolos de red (ODBC, JDBC o drivers nativos).</li><li><strong>Servidor (Back-End):</strong> Aloja el DBMS, procesa las sentencias SQL y administra los datos en disco.</li><li><em>Limitación:</em> Cada cliente requiere instalar drivers y credenciales directas a la base de datos, lo que dificulta la seguridad y el mantenimiento masivo.</li></ul><h3 id="_3-arquitectura-multicapas-3-o-mas-capas-estandar-web-api-actual" tabindex="-1">3. Arquitectura Multicapas (3 o más Capas - Estándar Web/API Actual) <a class="header-anchor" href="#_3-arquitectura-multicapas-3-o-mas-capas-estandar-web-api-actual" aria-label="Permalink to &quot;3. Arquitectura Multicapas (3 o más Capas - Estándar Web/API Actual)&quot;">​</a></h3><p>Es la arquitectura obligatoria en el desarrollo de software actual (Web, REST APIs y Microservicios):</p><ul><li><strong>Capa 1 (Cliente/Presentación):</strong> Navegador web, aplicación móvil (React, Vue, Flutter, HTML/CSS).</li><li><strong>Capa 2 (Servidor de Aplicaciones / Backend):</strong> Node.js/Express, Python/FastAPI, PHP/Laravel. Contiene la lógica de negocio y es la <strong>única</strong> que se conecta de manera segura a la base de datos mediante un pool de conexiones.</li><li><strong>Capa 3 (Servidor de Base de Datos):</strong> Servidor dedicado exclusivamente al motor PostgreSQL o MySQL, protegido tras un firewall y sin exposición directa a internet.</li></ul>',12)),(s(),t(d,null,{default:a(()=>[n(r,{id:"mermaid-150",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20User%5B%22Cliente%20Web%20%2F%20M%C3%B3vil%3Cbr%3E(Capa%201%3A%20Presentaci%C3%B3n)%22%5D%20--%20HTTP%20%2F%20REST%20%2F%20JSON%20--%3E%20API%5B%22Servidor%20de%20Aplicaci%C3%B3n%20(Node.js)%3Cbr%3E(Capa%202%3A%20L%C3%B3gica%20de%20Negocio)%22%5D%0A%20%20%20%20API%20--%20Pool%20de%20Conexiones%20TCP%20(Puerto%205432)%20--%3E%20DB%5B%22Servidor%20PostgreSQL%3Cbr%3E(Capa%203%3A%20Datos)%22%5D%0A"})]),fallback:a(()=>[...e[3]||(e[3]=[i(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=l('<hr><h2 id="🛡️-capitulo-iv-el-rol-responsabilidades-y-etica-del-administrador-de-bases-de-datos-dba" tabindex="-1">🛡️ CAPÍTULO IV: El Rol, Responsabilidades y Ética del Administrador de Bases de Datos (DBA) <a class="header-anchor" href="#🛡️-capitulo-iv-el-rol-responsabilidades-y-etica-del-administrador-de-bases-de-datos-dba" aria-label="Permalink to &quot;🛡️ CAPÍTULO IV: El Rol, Responsabilidades y Ética del Administrador de Bases de Datos (DBA)&quot;">​</a></h2><p>El <strong>Administrador de Bases de Datos (DBA)</strong> es el profesional responsable del control operacional, la seguridad, la integridad y el rendimiento continuo de las bases de datos de una organización.</p><h3 id="tareas-primordiales-del-dba" tabindex="-1">Tareas Primordiales del DBA: <a class="header-anchor" href="#tareas-primordiales-del-dba" aria-label="Permalink to &quot;Tareas Primordiales del DBA:&quot;">​</a></h3><ol><li><strong>Instalación y Configuración del DBMS:</strong> Afinamiento de memoria compartida, búferes de disco y concurrencia máxima.</li><li><strong>Diseño Físico e Indexación:</strong> Creación de índices eficientes para acelerar consultas sin degradar las escrituras.</li><li><strong>Seguridad y Control de Acceso:</strong> Gestión de roles, usuarios, asignación de privilegios mínimos necesarios y auditoría de accesos.</li><li><strong>Estrategias de Respaldo y Recuperación (Backup &amp; Restore):</strong><ul><li><em>Cold Backup (Respaldo en frío):</em> Se detiene el motor y se copian los archivos binarios.</li><li><em>Hot Backup (Respaldo en caliente / Lógico):</em> Herramientas como <code>pg_dump</code> o <code>mysqldump</code> que extraen el DDL y los datos sin interrumpir el servicio.</li><li><em>Transacciones WAL (Write-Ahead Logging):</em> Bitácora secuencial para restaurar el estado exacto de la base de datos hasta un segundo antes de un fallo eléctrico.</li></ul></li><li><strong>Monitoreo y Detección de Cuellos de Botella:</strong> Identificación de consultas lentas (<em>slow queries</em>) y optimización de planes de ejecución (<code>EXPLAIN ANALYZE</code>).</li></ol><hr><h2 id="📝-resumen-y-preguntas-guia-para-la-evaluacion-1" tabindex="-1">📝 Resumen y Preguntas Guía para la Evaluación 1 <a class="header-anchor" href="#📝-resumen-y-preguntas-guia-para-la-evaluacion-1" aria-label="Permalink to &quot;📝 Resumen y Preguntas Guía para la Evaluación 1&quot;">​</a></h2><p>Al finalizar esta unidad, el estudiante debe ser capaz de argumentar con solidez:</p><ul><li>¿Por qué un sistema basado en hojas de cálculo Excel o ficheros de texto no es una base de datos profesional?</li><li>¿Qué nivel de la arquitectura ANSI/SPARC se ve afectado si creamos un nuevo índice en PostgreSQL?</li><li>¿Por qué en una arquitectura de 3 capas la aplicación frontend nunca debe conectarse directamente al puerto de la base de datos?</li><li>¿Cuáles son las diferencias fundamentales entre el rol de un Administrador de Datos (DA) y el Administrador de Bases de Datos (DBA)?</li></ul>',9))])}const E=c(p,[["render",A]]);export{S as __pageData,E as default};
